// Pretend sandbox activities with real git: every "VM" is a folder, origin.git plays the broker's git proxy.
import { execFile } from 'node:child_process';
import { mkdir, rm, writeFile } from 'node:fs/promises';
import { promisify } from 'node:util';
import { ApplicationFailure, heartbeat, sleep } from '@temporalio/activity';

const exec = promisify(execFile);
const git = (cwd, ...args) => exec('git', args, { cwd }).then((r) => r.stdout.trim()); // argv, never a shell string
const now = () => new Date().toTimeString().slice(0, 8);
const STEPS = ['read the table code', 'write the failing tests', 'add the empty-state card', 'hide the card while loading', 'handle a filter with no match', 'tidy up'];
let vmCount = 0;
let deathsLeft = Number(process.env.DEATHS ?? 1); // how many VMs will freeze at step 4

export const mainHead = async () => git('origin.git', 'rev-parse', 'main');

export const acquireSandbox = async (ticket) => {
  const vm = { id: `i-0${String(++vmCount).padStart(3, '0')}`, ticket };
  console.log(`${now()}  claimed a fresh VM ${vm.id}`);
  return vm;
};

export const freshenSandbox = async (vm, sha) => {
  await rm(`vms/${vm.id}`, { recursive: true, force: true });
  await mkdir('vms', { recursive: true });
  await exec('git', ['clone', '--quiet', 'origin.git', `vms/${vm.id}`]);
  await git(`vms/${vm.id}`, 'checkout', '--quiet', '-B', `nova/${vm.ticket}`, sha);
  console.log(`${now()}  ${vm.id} freshened at ${sha.slice(0, 7)}`);
};

export const workInSandbox = async (vm, fromStep) => {
  const dir = `vms/${vm.id}`;
  let checkpoint;
  for (let step = fromStep; step <= STEPS.length; step++) {
    console.log(`${now()}  ${vm.id} step ${step}: ${STEPS[step - 1]} ...`);
    await sleep(1500);
    if (step === 4 && deathsLeft > 0) {
      deathsLeft -= 1;
      console.log(`${now()}  ${vm.id} froze (no heartbeat), so the activity gives up on it`);
      throw ApplicationFailure.create({ type: 'SandboxDead', message: `${vm.id} stopped sending heartbeats`, nonRetryable: true, details: [checkpoint] });
    }
    await writeFile(`${dir}/step-${step}.txt`, `${STEPS[step - 1]}\n`);
    await git(dir, 'add', '-A');
    await git(dir, '-c', 'user.name=Nova', '-c', 'user.email=nova@example.com', 'commit', '--quiet', '-m', `wip(${vm.ticket}): ${STEPS[step - 1]} [skip ci]`);
    await git(dir, 'push', '--quiet', 'origin', `HEAD:refs/heads/nova/${vm.ticket}`);
    checkpoint = { sha: await git(dir, 'rev-parse', 'HEAD'), step };
    heartbeat(checkpoint); // the heartbeat carries the latest checkpoint
    console.log(`${now()}  ${vm.id} checkpoint ${checkpoint.sha.slice(0, 7)} after step ${step}`);
  }
  return `all ${STEPS.length} steps done on ${vm.id}`;
};

export const releaseSandbox = async (vm) => {
  await rm(`vms/${vm.id}`, { recursive: true, force: true });
  console.log(`${now()}  ${vm.id} destroyed`);
};

export const notify = async (ticket, text) => console.log(`${now()}  Slack thread for ${ticket}: "${text}"`);
export const handBack = async (ticket, why) => console.log(`${now()}  Jira ${ticket}: assigned back to the requester (${why})`);
EOF

