const MAX_LOST_VMS = 2;

// A VM is only a workbench: if it dies, take a fresh one and carry on from the last checkpoint.
const runWithRecovery = async (state, ticket, base) => {
  for (;;) {
    const vm = await act.acquireSandbox(ticket);
    try {
      await act.freshenSandbox(vm, state.checkpoint?.sha ?? base);
      return await act.workInSandbox(vm, (state.checkpoint?.step ?? 0) + 1);
    } catch (err) {
      const failure = err instanceof ActivityFailure && err.cause instanceof ApplicationFailure ? err.cause : undefined;
      if (failure?.type !== 'SandboxDead') throw err; // anything else is a real failure
      state.checkpoint = failure.details?.[0] ?? state.checkpoint; // the last checkpoint the dead VM reported
      state.lostVms += 1;
      if (state.lostVms >= MAX_LOST_VMS) {
        await act.notify(ticket, `This ticket lost two VMs in a row, so I stopped. Branch nova/${ticket} and my notes are saved; a person should take a look.`);
        await act.handBack(ticket, 'lost two VMs in a row');
        throw ApplicationFailure.create({ type: 'NeedsPerson', message: 'two lost VMs', nonRetryable: true });
      }
    } finally {
      await CancellationScope.nonCancellable(() => act.releaseSandbox(vm)); // the dead VM is destroyed, never reused
    }
  }
};
